import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path p = Path.of("demo.txt");
        String text = "\u4e2d\u6587abc";

        // 1) bytes in UTF-8: 3 bytes per CJK char, 1 byte per ASCII char
        Files.write(p, text.getBytes(StandardCharsets.UTF_8));
        System.out.println("text char count (UTF-16 code units) = " + text.length());
        System.out.println("bytes on disk (UTF-8)                = " + Files.size(p));

        // 2) decode with the SAME charset -> identical
        String ok = new String(Files.readAllBytes(p), StandardCharsets.UTF_8);
        System.out.println("decode UTF-8   -> equals original : " + ok.equals(text));

        // 3) decode with a WRONG charset -> mojibake (different length, not equal)
        String bad = new String(Files.readAllBytes(p), StandardCharsets.ISO_8859_1);
        System.out.println("decode latin1  -> equals original : " + bad.equals(text));
        System.out.println("decode latin1  -> char count      : " + bad.length());
        System.out.println("latin1 maps every byte to one char: " + (bad.length() == Files.size(p)));

        // 4) chars vs bytes when reading through a Reader
        int chars = 0, bytes = 0;
        try (Reader r = Files.newBufferedReader(p, StandardCharsets.UTF_8)) {
            while (r.read() != -1) chars++;
        }
        try (InputStream in = Files.newInputStream(p)) {
            while (in.read() != -1) bytes++;
        }
        System.out.println("Reader gives chars = " + chars + " ; InputStream gives bytes = " + bytes);
    }
}
